import { canonicalSha256 } from '../core/canonical-json.mjs';
import { compileScope } from './scope-compiler.mjs';
import { bundleWorkUnits } from './work-unit-bundler.mjs';
import { CoverageLedger } from './coverage-ledger.mjs';
import { resolveRules } from './rule-resolver.mjs';
import { anchorFindings } from './anchor-engine.mjs';
import { reflectFindings } from './reflection-pipeline.mjs';
export async function runHybridTechnique({technique,change,files,rules,taskClass,availableArtifacts=['source'],relations=[],agent}){if(typeof agent!=='function')throw new TypeError('agent function is required');const scope=compileScope({change,policy:{include:['**'],exclude:[]}});const bundles=bundleWorkUnits({scope,relations});const ledger=new CoverageLedger(bundles);const agentFindings=[];const deterministicFailures=[];for(const unit of bundles.units){const workerId=`agent:${technique.id}`;ledger.start(unit.unitId,workerId);const resolution=resolveRules({rules,unit,taskClass,availableArtifacts});try{const output=await agent({technique,unit,rules:resolution.selected,scope});agentFindings.push(...(output??[]));ledger.complete(unit.unitId,{receiptSha256:canonicalSha256({unitId:unit.unitId,output})});}catch(error){const failure={id:`deterministic-${unit.unitId}`,severity:'critical',message:`Agent stage failed: ${error.message}`,receiptSha256:canonicalSha256({unitId:unit.unitId,error:error.message})};deterministicFailures.push(failure);ledger.complete(unit.unitId,{receiptSha256:failure.receiptSha256});}}const anchored=anchorFindings({findings:agentFindings,files});for(const rejected of anchored.rejected)deterministicFailures.push({id:`anchor-${rejected.id}`,severity:'high',message:`Finding could not be anchored: ${rejected.reason}`,receiptSha256:canonicalSha256(rejected)});const reflected=reflectFindings({deterministicFailures,agentFindings:anchored.accepted.map((item)=>({...item,evidenceSpans:[item.anchor]}))});const coverage=ledger.assertComplete();const payload={schemaVersion:1,techniqueId:technique.id,status:reflected.status,scope,bundles,coverage,findings:reflected.final,rejected:reflected.rejected,anchorReceiptSha256:anchored.anchorReceiptSha256};return Object.freeze({...payload,runSha256:canonicalSha256(payload)});}
